<!DOCTYPE html>
<html lang="id">

<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Login Admin</title>

    <!-- Fonts -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">

    <!-- Icon -->
    <script src="https://kit.fontawesome.com/26af10689e.js" crossorigin="anonymous"></script>

    <!-- Bootstrap 4 + AdminLTE lokal (sama seperti halaman lain) -->
    <link rel="stylesheet" href="{{ asset('assets/plugins/dist/css/adminlte.min.css') }}">

    <style>
        :root {
            --lp-primary: #5A67D8;
            --lp-primary-dark: #4C51BF;
            --lp-primary-soft: #EEF0FF;
            --lp-ink: #1A202C;
            --lp-muted: #64748B;
            --lp-border: #DCE1F2;
        }

        body.login-body {
            font-family: 'Inter', sans-serif;
            color: var(--lp-ink);
            background: linear-gradient(180deg, #E6ECFF 0%, #DAE3FF 55%, #CBD7FA 100%);
            margin: 0;
            min-height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 24px 16px;
            overflow: hidden;
            transition: opacity .25s ease;
        }

        body.login-body.leaving { opacity: 0; }

        /* ---------- Latar: peta Indonesia dengan titik berdenyut ---------- */
        .bg-map {
            position: fixed;
            left: 50%;
            top: 54%;
            width: clamp(780px, 96vw, 1250px);
            transform: translate(-50%, -50%);
            pointer-events: none;
            z-index: 0;
            animation: mapBreath 12s ease-in-out infinite;
            /* Peta memudar di sekitar form agar tulisan tetap jelas */
            -webkit-mask-image: radial-gradient(ellipse 25% 50% at 50% 44%, rgba(0, 0, 0, .3) 45%, #000 100%);
            mask-image: radial-gradient(ellipse 25% 50% at 50% 44%, rgba(0, 0, 0, .3) 45%, #000 100%);
        }

        .bg-map svg { display: block; width: 100%; height: auto; overflow: visible; }

        .bg-map .prov path {
            fill: rgba(90, 103, 216, .15);
            stroke: rgba(255, 255, 255, .8);
            stroke-width: 1.1;
            stroke-linejoin: round;
            opacity: 0;
            animation: provIn .9s ease forwards;
            animation-delay: calc(var(--i) * 45ms + .2s);
        }

        .bg-map .route {
            fill: none;
            stroke: rgba(90, 103, 216, .5);
            stroke-width: 1.3;
            stroke-dasharray: 4 7;
            stroke-linecap: round;
            animation: routeMove 3s linear infinite;
        }

        .bg-map .dot .core { fill: #4C51BF; }

        .bg-map .dot .ring {
            fill: none;
            stroke: #5A67D8;
            stroke-width: 1.6;
            transform-box: fill-box;
            transform-origin: center;
            animation: ping 3s ease-out infinite;
            animation-delay: var(--d);
        }

        /* Pendar lembut di belakang form */
        .bg-glow {
            position: fixed;
            left: 50%;
            top: 42%;
            width: 700px;
            height: 700px;
            transform: translate(-50%, -50%);
            background: radial-gradient(circle, rgba(139, 112, 240, .20) 0%, rgba(110, 130, 235, .12) 38%, rgba(110, 130, 235, 0) 68%);
            pointer-events: none;
            z-index: 0;
            animation: glow 7s ease-in-out infinite;
        }

        /* ---------- Form (tanpa card) ---------- */
        .auth-box {
            position: relative;
            z-index: 1;
            width: 100%;
            max-width: 330px;
        }

        .auth-box.shake { animation: shake .5s .5s both; }

        /* Muncul berurutan */
        .auth-box .stagger {
            opacity: 0;
            animation: fadeUp .7s cubic-bezier(.2, .8, .2, 1) forwards;
        }

        .auth-box .stagger:nth-child(1) { animation-delay: .1s; }
        .auth-box .stagger:nth-child(2) { animation-delay: .22s; }
        .auth-box .stagger:nth-child(3) { animation-delay: .34s; }
        .auth-box .stagger:nth-child(4) { animation-delay: .46s; }

        .brand {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 10px;
            font-weight: 800;
            font-size: 1rem;
            letter-spacing: -.01em;
            margin-bottom: 26px;
        }

        .brand .logo {
            width: 36px;
            height: 36px;
            border-radius: 11px;
            background: linear-gradient(135deg, var(--lp-primary), #8B5CF6);
            color: #fff;
            display: grid;
            place-items: center;
            font-size: 16px;
            box-shadow: 0 8px 20px rgba(90, 103, 216, .3);
        }

        .login-title {
            font-size: 1.7rem;
            font-weight: 800;
            letter-spacing: -.02em;
            margin: 0 0 4px;
            text-align: center;
        }

        .login-sub {
            color: var(--lp-muted);
            text-align: center;
            margin-bottom: 24px;
            font-size: .92rem;
        }

        /* ---------- Input ---------- */
        .field {
            position: relative;
            margin-bottom: 14px;
        }

        .field > .lead-ico {
            position: absolute;
            left: 16px;
            top: 50%;
            transform: translateY(-50%);
            color: var(--lp-muted);
            font-size: .88rem;
            pointer-events: none;
            transition: color .2s;
            z-index: 1;
        }

          /* Input glass tanpa kotak: hanya garis bawah, efek kaca tetap ada */
        .field .form-control {
            height: 48px;
            padding-left: 44px;
            border: 0;
            border-bottom: 1.5px solid rgba(255, 255, 255, .85);
            border-radius: 12px 12px 0 0;
            background: linear-gradient(180deg, rgba(255, 255, 255, .24) 0%, rgba(255, 255, 255, .08) 100%);
            -webkit-backdrop-filter: blur(10px) saturate(150%);
            backdrop-filter: blur(10px) saturate(150%);
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, .45);
            font-size: .95rem;
            font-weight: 500;
            color: var(--lp-ink);
            transition: background .25s, box-shadow .25s;
        }

        .field .form-control::placeholder { color: #75819B; font-weight: 400; }

        .field .form-control:hover {
            background: linear-gradient(180deg, rgba(255, 255, 255, .34) 0%, rgba(255, 255, 255, .14) 100%);
        }

        .field .form-control:focus {
            background: linear-gradient(180deg, rgba(255, 255, 255, .42) 0%, rgba(255, 255, 255, .18) 100%);
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, .55), 0 14px 24px -16px rgba(76, 81, 191, .45);
        }

        /* Garis aktif gradasi ungu yang tumbuh dari tengah saat difokus */
        .field::after {
            content: '';
            position: absolute;
            left: 0;
            right: 0;
            bottom: 0;
            height: 2px;
            background: linear-gradient(90deg, var(--lp-primary), #8B5CF6);
            border-radius: 2px;
            transform: scaleX(0);
            transform-origin: center;
            transition: transform .35s cubic-bezier(.2, .8, .2, 1);
            pointer-events: none;
            z-index: 2;
        }

        .field:focus-within::after { transform: scaleX(1); }

        .field .toggle-pass {
            position: absolute;
            right: 8px;
            top: 50%;
            transform: translateY(-50%);
            width: 34px;
            height: 34px;
            border: 0;
            border-radius: 9px;
            background: transparent;
            color: var(--lp-muted);
            cursor: pointer;
            display: grid;
            place-items: center;
            transition: all .2s;
            z-index: 1;
        }

        .field .toggle-pass:hover { background: var(--lp-primary-soft); color: var(--lp-primary); }
        .field .toggle-pass:focus { outline: none; box-shadow: 0 0 0 3px rgba(90, 103, 216, .2); }
        .field.has-toggle .form-control { padding-right: 48px; }

        /* ---------- Tombol ---------- */
        .btn-login {
            position: relative;
            width: 100%;
            height: 46px;
            margin-top: 12px;
            border: 0;
            border-radius: 999px;
            background: linear-gradient(135deg, var(--lp-primary), #7C6CE6);
            color: #fff;
            font-weight: 700;
            font-size: .95rem;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            overflow: hidden;
            cursor: pointer;
            box-shadow: 0 10px 24px rgba(90, 103, 216, .26);
            transition: transform .2s, box-shadow .2s, filter .2s;
        }

        .btn-login:hover { filter: brightness(.95); transform: translateY(-2px); box-shadow: 0 14px 28px rgba(90, 103, 216, .34); }
        .btn-login:active { transform: translateY(0) scale(.98); }
        .btn-login:focus { outline: none; box-shadow: 0 0 0 4px rgba(90, 103, 216, .25); }

        .btn-login::after {
            content: '';
            position: absolute;
            top: 0;
            left: -80%;
            width: 50%;
            height: 100%;
            background: linear-gradient(120deg, transparent, rgba(255, 255, 255, .35), transparent);
            transform: skewX(-20deg);
        }

        .btn-login:hover::after { animation: shine .8s ease; }

        .btn-login .arrow { transition: transform .2s; }
        .btn-login:hover .arrow { transform: translateX(4px); }

        .btn-login.loading { pointer-events: none; opacity: .85; }

        .btn-login .spinner {
            display: none;
            width: 18px;
            height: 18px;
            border: 2px solid rgba(255, 255, 255, .45);
            border-top-color: #fff;
            border-radius: 50%;
            animation: spin .7s linear infinite;
        }

        .btn-login.loading .spinner { display: inline-block; }
        .btn-login.loading .arrow { display: none; }

        .back-link {
            margin-top: 24px;
            text-align: center;
        }

        .back-link a {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            color: var(--lp-muted);
            font-size: .88rem;
            font-weight: 600;
            text-decoration: none !important;
            transition: color .2s;
        }

        .back-link a i { transition: transform .2s; }
        .back-link a:hover { color: var(--lp-primary); }
        .back-link a:hover i { transform: translateX(-4px); }

        /* ---------- Keyframes ---------- */
        @keyframes mapBreath {
            0%, 100% { transform: translate(-50%, -50%) scale(1); }
            50% { transform: translate(-50%, -50%) scale(1.025); }
        }

        @keyframes provIn {
            from { opacity: 0; }
            to { opacity: 1; }
        }

        @keyframes routeMove {
            to { stroke-dashoffset: -22; }
        }

        @keyframes ping {
            0% { transform: scale(1); opacity: .8; }
            80%, 100% { transform: scale(5.5); opacity: 0; }
        }

        @keyframes glow {
            0%, 100% { opacity: .85; transform: translate(-50%, -50%) scale(1); }
            50% { opacity: 1; transform: translate(-50%, -50%) scale(1.08); }
        }

        @keyframes fadeUp {
            from { opacity: 0; transform: translateY(16px); }
            to { opacity: 1; transform: none; }
        }

        @keyframes shine {
            to { left: 140%; }
        }

        @keyframes spin {
            to { transform: rotate(360deg); }
        }

        @keyframes shake {
            10%, 90% { transform: translateX(-2px); }
            20%, 80% { transform: translateX(4px); }
            30%, 50%, 70% { transform: translateX(-6px); }
            40%, 60% { transform: translateX(6px); }
        }

        @media (prefers-reduced-motion: reduce) {
            .auth-box .stagger { animation: none !important; opacity: 1; }
            .bg-map,
            .bg-map .prov path,
            .bg-map .route,
            .bg-map .dot .ring,
            .bg-glow { animation: none !important; }
            .bg-map .prov path { opacity: 1; }
            body.login-body { transition: none; }
        }
    </style>
</head>

