    <!-- ========== /Notifikasi login ========== -->

    <script>
        // Tampilkan / sembunyikan password
        document.getElementById('togglePass').addEventListener('click', function() {
            const input = document.getElementById('password');
            const tampil = input.type === 'password';
            input.type = tampil ? 'text' : 'password';
            this.querySelector('i').className = tampil ? 'fas fa-eye-slash' : 'fas fa-eye';
            this.setAttribute('aria-label', tampil ? 'Sembunyikan password' : 'Tampilkan password');
        });

        // Animasi loading saat form dikirim (form tetap terkirim seperti biasa)
        document.getElementById('loginForm').addEventListener('submit', function() {
            const btn = document.getElementById('btnLogin');
            btn.classList.add('loading');
            btn.querySelector('.label').textContent = 'Memproses...';
        });

        // Memudar keluar saat kembali ke landing page
        document.querySelector('.back-link a').addEventListener('click', function(e) {
            const tujuan = this.href;
            if (e.ctrlKey || e.metaKey || e.shiftKey || e.button !== 0) return;
            e.preventDefault();
            document.body.classList.add('leaving');
            setTimeout(function() { window.location.href = tujuan; }, 250);
        });

        // Kembalikan tampilan jika halaman dibuka lagi lewat tombol Back browser
        window.addEventListener('pageshow', function(e) {
            document.body.classList.remove('leaving');
            if (e.persisted) {
                const btn = document.getElementById('btnLogin');
                btn.classList.remove('loading');
                btn.querySelector('.label').textContent = 'Login';
            }
        });
    </script>
</body>

